from minishop.utils import money

def checkout_total(cart):
    return money(cart.total_cents())

from minishop.cart import Cart

def bulk_total_cents(product, qty):
    c = Cart(member=False)
    c.add(product, qty)
    return c.subtotal_cents()

from minishop.utils import receipt_line

def receipt_for(cart):
    return "\n".join(receipt_line(l.product.name, l.qty, l.total_cents) for l in cart.lines)
